//! The game's story missions and side activities.
//!
//! They are the game's own Domino graphs (Lua generated by Ubisoft's visual
//! scripting tool), packed into the cache at conversion and run here on an
//! embedded Lua 5.1 (`fc3_domino`). The engine functions they call are
//! provided by this module: calls that act on the world are queued as
//! [`ScriptCommand`]s and applied by an ordinary system each frame, and
//! queries read a snapshot of the world taken before the scripts run
//! ([`WorldView`]).
//!
//! FC3_DOMINO_RUN=<graph path> runs a graph from the start once the world is
//! up, and FC3_DOMINO_TRACE logs the natives the scripts reach that aren't
//! provided yet.

use std::cell::RefCell;
use std::rc::Rc;

use bevy::prelude::*;
use fc3_domino::{Domino, ScriptSource};
use fc3_formats::scripts::{ScriptPack, DOMINO_PACK_REL};

use crate::data::CacheInfo;
use crate::player::Player;

pub struct StoryPlugin;

impl Plugin for StoryPlugin {
    fn build(&self, app: &mut App) {
        app.add_systems(Update, start_scripts.run_if(resource_exists::<CacheInfo>))
            .add_systems(Update, (refresh_view, run_scripts, apply_commands).chain().run_if(scripts_running));
    }
}

/// Something a script asked of the world, applied after the scripts ran.
#[derive(Debug, Clone)]
pub enum ScriptCommand {
    /// A line for the screen (debug prints), for how many seconds.
    Print(String, f32),
}

/// What the scripts may read of the world, taken each frame before they run.
#[derive(Default)]
pub struct WorldView {
    pub player_position: Vec3,
    pub time: f32,
}

/// The scripts' side of the bridge: the queue they write to and the view
/// they read.
#[derive(Default)]
pub struct Bridge {
    pub commands: Vec<ScriptCommand>,
    pub view: WorldView,
}

/// The Lua state running the graphs (not `Send`: it lives on the main thread).
pub struct Scripts {
    pub domino: Domino,
    pub bridge: Rc<RefCell<Bridge>>,
    trace: bool,
}

/// The id the scripts know the player by. Entity ids are 64-bit, beyond
/// what a Lua 5.1 number holds exactly, so the scripts carry them as decimal
/// strings (as the graphs write the world's entity ids).
pub const PLAYER_ID: &str = "1";
/// No entity.
pub const INVALID_ID: &str = fc3_domino::INVALID_ID;

struct Pack(ScriptPack);

impl ScriptSource for Pack {
    fn script(&self, path: &str) -> Option<String> {
        self.0.get(path)
    }
}

fn scripts_running(scripts: Option<NonSend<Scripts>>) -> bool {
    scripts.is_some()
}

/// Loads the scripts once the cache is ready.
fn start_scripts(world: &mut World, mut tried: Local<bool>) {
    if *tried {
        return;
    }
    *tried = true;
    let root = world.resource::<CacheInfo>().root.clone();
    let pack = match std::fs::read(root.join(DOMINO_PACK_REL)).map_err(anyhow::Error::from).and_then(|b| ScriptPack::from_bytes(&b)) {
        Ok(p) => p,
        Err(e) => {
            warn!("no mission scripts in the cache ({e:#}): the story is off");
            return;
        }
    };
    info!("{} mission scripts", pack.len());
    let domino = match Domino::new(Pack(pack)) {
        Ok(d) => d,
        Err(e) => {
            error!("mission scripts: {e}");
            return;
        }
    };
    let bridge = Rc::new(RefCell::new(Bridge::default()));
    if let Err(e) = register_natives(&domino, &bridge) {
        error!("mission scripts: {e}");
        return;
    }
    let scripts = Scripts { domino, bridge, trace: std::env::var("FC3_DOMINO_TRACE").is_ok() };
    if let Ok(path) = std::env::var("FC3_DOMINO_RUN") {
        match scripts.domino.create(&path).and_then(|g| scripts.domino.call(&g, "In")) {
            Ok(()) => info!("started {path}"),
            Err(e) => error!("{path}: {e}"),
        }
    }
    world.insert_non_send_resource(scripts);
}

/// The engine functions the scripts call.
fn register_natives(d: &Domino, bridge: &Rc<RefCell<Bridge>>) -> mlua::Result<()> {
    d.register("GetLocalPlayerId", |_, ()| Ok(PLAYER_ID))?;
    d.register("GetInvalidEntityId", |_, ()| Ok(INVALID_ID))?;
    // Names compared by id: CRC-32, of the text as given or in lower case.
    d.register("GetStringID", |_, text: Option<String>| Ok(fc3_formats::hash::crc32(text.unwrap_or_default().as_bytes())))?;
    d.register("GetNoCaseStringID", |_, text: Option<String>| {
        Ok(fc3_formats::hash::crc32(text.unwrap_or_default().to_ascii_lowercase().as_bytes()))
    })?;
    let b = bridge.clone();
    d.register("LogConsole", move |_, text: Option<String>| {
        let _ = &b;
        info!("script: {}", text.unwrap_or_default());
        Ok(())
    })?;
    let b = bridge.clone();
    d.register("DrawTextToScreen", move |_, (text, seconds): (Option<String>, Option<f32>)| {
        b.borrow_mut().commands.push(ScriptCommand::Print(text.unwrap_or_default(), seconds.unwrap_or(3.0)));
        Ok(())
    })?;
    // The graphs' log text (a localised-string lookup in the game; the
    // generated graphs pass plain text).
    d.register("GetStringIDLogStr", |_, text: Option<String>| Ok(text))?;
    Ok(())
}

fn refresh_view(scripts: NonSend<Scripts>, time: Res<Time>, player: Query<&GlobalTransform, With<Player>>) {
    let mut b = scripts.bridge.borrow_mut();
    b.view.time = time.elapsed_secs();
    if let Ok(p) = player.single() {
        b.view.player_position = p.translation();
    }
}

fn run_scripts(scripts: NonSend<Scripts>) {
    if scripts.trace {
        for call in scripts.domino.take_unknown_calls() {
            info!("script native not provided: {call}");
        }
    } else {
        scripts.domino.take_unknown_calls();
    }
}

fn apply_commands(scripts: NonSend<Scripts>) {
    let commands = std::mem::take(&mut scripts.bridge.borrow_mut().commands);
    for c in commands {
        match c {
            ScriptCommand::Print(text, _) => info!("script print: {text}"),
        }
    }
}
